  let artifactId: string = $state('');
  let targetType: string = $state('');
  let deploying: boolean = $state(false);
  let error: string = $state('');

  async function triggerDeploy() {
    deploying = true;
    error = "";
    await (async () => { const __r = await fetch("/api/deploy", { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ artifact_id: artifactId, target: targetType }) }); if (!__r.ok) throw new Error(await __r.text()); const __t = await __r.text(); return __t ? JSON.parse(__t) : null; })();
    deploying = false;
  }
</script>

<div class="deploy">
  <PageHeader title="Deploy" description="Publish an artifact to a target runtime." />
  <form class="dk-form card" onsubmit={(e) => { e.preventDefault(); triggerDeploy(); }}>
    <FormSection title="Artifact" columns={1}>
      <FormField label="Artifact ID" bind:value={artifactId} required={true} placeholder="art_…" />
      <div class="dk-field">
        <label class="dk-field__label" for="deploy-target">Target</label>
        <div class="dk-field__control">
          <select id="deploy-target" bind:value={targetType}>
            <option value="lambda">Lambda</option>
